const SERIF = '"PT Serif", Georgia, serif';
const SANS = '"Quattrocento Sans", sans-serif';

function textLines(context, text, width) {
  // Word boundaries for Latin scripts, character boundaries for CJK.
  const tokens = String(text || '').match(/[\u2E80-\u9FFF\uF900-\uFAFF]|[^\s\u2E80-\u9FFF\uF900-\uFAFF]+\s*/g) || [];
  const lines = [];
  let line = '';
  for (const token of tokens) {
    if (line && context.measureText(line + token).width > width) { lines.push(line.trim()); line = token; }
    else line += token;
  }
  if (line) lines.push(line.trim());
  return lines;
}

function wrapText(context, text, x, y, width, lineHeight, limit = Infinity) {
  const lines = textLines(context, text, width);
  lines.slice(0, limit).forEach((value, index) => context.fillText(value + (index === limit - 1 && lines.length > limit ? '…' : ''), x, y + index * lineHeight));
  return y + Math.min(lines.length, limit) * lineHeight;
}

